# Function to play metronome sound
def play_metronome():
    global METRONOME_SPEED
    while True:
        pygame.mixer.music.play()
        time.sleep(METRONOME_SPEED / 60)
        pygame.mixer.music.stop()
        time.sleep(1)
        METRONOME_SPEED = random.choice(METRONOME_SPEEDS)

# Start the metronome in a separate thread
metronome_thread = threading.Thread(target=play_metronome)
metronome_thread.daemon = True
metronome_thread.start()

@app.route('/')
def index():
    return render_template('index.html')

@app.route('/uploads/<filename>')
def uploaded_file(filename):
    return send_from_directory(app.config['UPLOAD_FOLDER'], filename)

if __name__ == '__main__':
    app.run(debug=True)
```

